def T(id, name, *cs): return {'id': id, 'name': name, 'concourses': [{'id': c[0], 'name': c[1], 'gates': c[2], 'airside': c[3]} for c in cs]}
def I(name, desc, vegan, *src): return (name, desc, vegan, list(src))
# a spot: name, level (concourse id after security, terminal id before it), gates, zone, where, items, note
def P(name, level, gates, zone, where, items, note=None): return dict(name=name, level=level, gates=gates, zone=zone, where=where, items=items, note=note)
