def q(s): return "'" + str(s).replace("'", "''") + "'"
def src(keys): return [{'label': S[k][0], 'url': S[k][1], 'date': S[k][2]} for k in keys]

out = ["-- The Airport Guide's first sixteen airports (Sean, 2026-10-29), written by scripts/airport-guide/seed.py from four research passes",
       "-- over 2024 to 2026 sources. Safe to run twice: an airport already there is left as it is.", ""]
for n, ap in enumerate(AIRPORTS):
    layout = {'terminals': ap['layout']}
    out.append("insert into public.ve_venues (slug, name, kind, city, state, hub, teams, free_example, radius_m, sort_order, layout, image_url, status)")
    out.append("select %s, %s, 'airport', %s, %s, %s, array[%s], %s, %d, %d, %s::jsonb, %s, 'live' where not exists (select 1 from public.ve_venues where slug = %s);" % (
        q(ap['slug']), q(ap['name']), q(ap['city']), q(ap['state']), q(ap['hub']), q(ap['code']), 'true' if ap.get('free') else 'false',
        ap['radius'], 100 + n, q(json.dumps(layout)), q('/public/guides/airports/%s.webp' % ap['slug']), q(ap['slug'])))
    for i, sp in enumerate(ap['spots']):
        out.append("with v as (select id from public.ve_venues where slug = %s), s as (insert into public.ve_venue_spots (venue_id, name, where_text, zone, note, sort_order, map_sections, map_level)" % q(ap['slug']))
        out.append("  select v.id, %s, %s, %s, %s, %d, array[%s]::text[], %s from v where not exists (select 1 from public.ve_venue_spots x where x.venue_id = v.id and x.name = %s and x.where_text = %s) returning id, venue_id)" % (
            q(sp['name']), q(sp['where']), q(sp['zone']), q(sp['note']) if sp['note'] else 'null', i + 1, ', '.join(q(g) for g in sp['gates']), q(sp['level']), q(sp['name']), q(sp['where'])))
        rows = ', '.join("(%s, %s, %s, %s::jsonb, %d)" % (q(it[0]), q(it[1]) if it[1] else 'null', q(it[2]), q(json.dumps(src(it[3]))), j + 1) for j, it in enumerate(sp['items']))
        out.append("insert into public.ve_venue_items (venue_id, spot_id, name, description, vegan, sources, sort_order) select s.venue_id, s.id, x.n, x.d, x.v, x.src, x.o from s, (values %s) as x(n, d, v, src, o);" % rows)
    out.append("")
open(os.path.join(os.path.dirname(__file__), '..', '..', 'supabase', 'migrations', '20261029_airports_seed.sql'), 'w').write('\n'.join(out) + '\n')
print(len(AIRPORTS), 'airports,', sum(len(a['spots']) for a in AIRPORTS), 'spots,', sum(len(s['items']) for a in AIRPORTS for s in a['spots']), 'items')
